# -*- coding: utf-8 -*-# config.py - Chrono24 BI Dashboardimport plotly.graph_objects as goC = {    "bg":     "#0F0F23",    "card":   "#12122A",    "card2":  "#1A1A35",    "blue":   "#1A73E8",    "green":  "#34A853",    "orange": "#FBBC04",    "red":    "#EA4335",    "purple": "#9334E6",    "teal":   "#00BCD4",    "text":   "#FFFFFF",    "muted":  "#AAAAAA",    "border": "#333355",    "grid":   "#1E1E3A",}HEATMAP_SCALE = [    [0.0, "#0F0F23"], [0.25, "#1A3A6E"],    [0.5, "#1A73E8"], [0.75, "#34A853"], [1.0, "#FBBC04"],]HEALTH_COLORS = {    "Sain":              C["green"],    "\u00c0 surveiller": C["orange"],    "En danger":         C["red"],}ALERT_COLORS = {    "OK":     C["green"],    "LOW":    C["teal"],    "MEDIUM": C["orange"],    "HIGH":   C["red"],}HEALTH_SAIN        = 72HEALTH_SURVEILLER  = 55SAT_GLOBAL         = 4.821TOTAL_TRANSACTIONS = 175968PCT_INTERNATIONAL  = 72.1NB_SELLERS         = 2309PLOTLY_BASE = dict(    paper_bgcolor=C["bg"],    plot_bgcolor=C["card"],    font=dict(color=C["text"], family="Arial, sans-serif", size=12),    title_font=dict(size=15, color=C["text"]),    legend=dict(        bgcolor=C["card2"],        bordercolor=C["border"],        borderwidth=1,        font=dict(color=C["muted"])    ),    margin=dict(l=20, r=20, t=55, b=30),    hoverlabel=dict(        bgcolor=C["card2"],        bordercolor=C["border"],        font=dict(color=C["text"])    ),)AXIS_STYLE = dict(    gridcolor=C["grid"],    gridwidth=0.5,    linecolor=C["border"],    tickcolor=C["border"],    tickfont=dict(color=C["muted"]),    title_font=dict(color=C["muted"]),    showgrid=True,    zeroline=False,)def to_rgba(hex_color, alpha=0.2):    h = hex_color.lstrip("#")    r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)    return "rgba({},{},{},{})".format(r, g, b, alpha)def apply_theme(fig, title=""):    fig.update_layout(title_text=title, **PLOTLY_BASE)    fig.update_xaxes(**AXIS_STYLE)    fig.update_yaxes(**AXIS_STYLE)    return fig